const RESUME_B64 = "";
(function(){
  var resumeBtn = document.getElementById('resumeBtn');
  if (resumeBtn) {
    resumeBtn.addEventListener('click', async function(e){
      e.preventDefault();
      try {
        const downloads = await claude.use('downloads');
        if (downloads) {
          await downloads.save({ filename: 'Vincent-Valencia-Resume.pdf', data: RESUME_B64 });
          return;
        }
      } catch (err) {}
      const link = document.createElement('a');
      link.href = 'data:application/pdf;base64,' + RESUME_B64;
      link.download = 'Vincent-Valencia-Resume.pdf';
      link.click();
    });
  }
})();
(function(){
  var revealEls = document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window){
    var obs = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target); }
      });
    }, {threshold:0.15});
    revealEls.forEach(function(el){ obs.observe(el); });
  } else {
    revealEls.forEach(function(el){ el.classList.add('visible'); });
  }

  var timeline = document.querySelector('.timeline');
  var fill = document.querySelector('.timeline-fill');
  var dots = document.querySelectorAll('.tl-item');
  function updateFill(){
    if(!timeline || !fill) return;
    var rect = timeline.getBoundingClientRect();
    var vh = window.innerHeight;
    var total = rect.height;
    var visible = Math.min(Math.max(vh*0.75 - rect.top, 0), total);
    var pct = total ? (visible/total)*100 : 0;
    fill.style.height = pct + '%';
    dots.forEach(function(item){
      var r = item.getBoundingClientRect();
      if(r.top < vh*0.75){ item.classList.add('lit'); }
    });
  }
  window.addEventListener('scroll', updateFill, {passive:true});
  window.addEventListener('resize', updateFill);
  updateFill();
})();